66	lv_display_t * lv_nuttx_lcd_create(const char * dev_path)
67	{
68	    struct fb_videoinfo_s vinfo;
69	    struct lcd_planeinfo_s pinfo;
70	    lv_display_t * disp;
71	    int fd;
72	    int ret;
73	
74	    LV_ASSERT_NULL(dev_path);
75	
76	    LV_LOG_USER("lcd %s opening", dev_path);
77	    fd = open(dev_path, O_CLOEXEC);
78	    if(fd < 0) {
79	        perror("Error: cannot open lcd device");
80	        return NULL;
81	    }
82	
83	    LV_LOG_USER("lcd %s open success", dev_path);
84	
85	    ret = ioctl(fd, LCDDEVIO_GETVIDEOINFO,
86	                (unsigned long)((uintptr_t)&vinfo));
87	    if(ret < 0) {
88	        perror("Error: ioctl(LCDDEVIO_GETVIDEOINFO) failed");
89	        close(fd);
90	        return NULL;
91	    }
92	
93	    ret = ioctl(fd, LCDDEVIO_GETPLANEINFO,
94	                (unsigned long)((uintptr_t)&pinfo));
95	    if(ret < 0) {
96	        perror("ERROR: ioctl(LCDDEVIO_GETPLANEINFO) failed");
97	        close(fd);
98	        return NULL;
99	    }
100	
101	    disp = lcd_init(fd, vinfo.xres, vinfo.yres);
102	    if(disp == NULL) {
103	        close(fd);
104	    }
105	
106	    return disp;
