   */

  {
    float sd2[AI_WATCH_MENU_MAX_ICONS];
    int sorted[AI_WATCH_MENU_MAX_ICONS];
    int visible_count = 0;
    int j;

    /* Compute d2 for all icons */

    for (i = 0; i < ctx->icon_count; i++)
      {
