    for (j = 0; j < MENU_MAX_VISIBLE; j++)
      {
        float best_d2 = 1e30f;
        int best_idx = -1;

        for (i = 0; i < ctx->icon_count; i++)
          {
            int k;
            int already = 0;

            if (sd2[i] >= best_d2)
              {
